def solve():
    memo = {}

    def get_value(paths, turn):
        # paths is a sorted tuple of path lengths
        state = (paths, turn)
        if state in memo:
            return memo[state]

        # Possible moves
        possible_moves = []
        for i, length in enumerate(paths):
            if length >= 2:
                for j in range(1, length):
                    # A tile covers squares j and j+1 in the path of length 'length'
                    # This splits the path into j-1 and length-j-1
                    new_paths = list(paths)
                    new_paths.pop(i)
                    if j - 1 > 0:
                        new_paths.append(j - 1)
                    if length - j - 1 > 0:
                        new_paths.append(length - j - 1)
                    new_paths.sort()
                    possible_moves.append(tuple(new_paths))

        if not possible_moves:
            return sum(paths)

        if turn == 0: # Alice (maximize)
            res = -float('inf')
            for next_paths in possible_moves:
                res = max(res, get_value(next_paths, 1))
            memo[state] = res
            return res
        else: # Bob (minimize)
            res = float('inf')
            for next_paths in possible_moves:
                res = min(res, get_value(next_paths, 0))
            memo[state] = res
            return res

    for n in range(1, 21):
        memo = {}
        print(f"n={n}, v={get_value((n,), 0)}")

